import os

MODEL_DIR = os.getenv("MAGI_MODEL_DIR", "./models")

YOLO_BUBBLE_MODEL_PATH  = os.path.join(MODEL_DIR, "bubble_best.pt")
YOLO_PANEL_MODEL_PATH   = os.path.join(MODEL_DIR, "panel_best.pt")
YOLO_FACE_MODEL_PATH    = os.path.join(MODEL_DIR, "face_best.pt")
EMBED_MODEL_PATH        = os.path.join(MODEL_DIR, "sgg_relation_model.pth")
CLASSIFIER_MODEL_PATH   = os.path.join(MODEL_DIR, "relation_classifier3.pth")

TESSERACT_CMD = os.getenv("TESSERACT_CMD")  # optional Windows override


def check_models(verbose=True):
    paths = {
        "bubble_best.pt":           YOLO_BUBBLE_MODEL_PATH,
        "panel_best.pt":            YOLO_PANEL_MODEL_PATH,
        "face_best.pt":             YOLO_FACE_MODEL_PATH,
        "sgg_relation_model.pth":   EMBED_MODEL_PATH,
        "relation_classifier3.pth": CLASSIFIER_MODEL_PATH,
    }
    status = {n: os.path.exists(p) for n, p in paths.items()}
    if verbose:
        for n, ok in status.items():
            print(f"  {'\u2713' if ok else '\u2717'} {n}  ({paths[n]})")
        if not all(status.values()):
            print("\nMissing models — run: python scripts/download_models.py")
    return status


if __name__ == "__main__":
    print(f"MODEL_DIR = {os.path.abspath(MODEL_DIR)}\n")
    check_models()
